parameters.inputSchema:
{
  "type": "object",
  "required": ["intent", "urgency", "detected_anger", "escalate", "escalate_reason", "confidence"],
  "properties": {
    "intent": { "type": "string", "description": "Exactly one of: General Question, Pricing Question, Booking or Scheduling, Refund Request, Complaint, Legal or Medical Question, Other." },
    "urgency": { "type": "string", "description": "Exactly one of: Low, Medium, High. High means same-day response needed." },
    "detected_anger": { "type": "string", "description": "The literal string 'true' if the message shows frustration, anger, or hostile tone, otherwise the literal string 'false'." },
    "escalate": { "type": "string", "description": "The literal string 'true' if this is a refund request, a complaint, contains legal or medical language, detected_anger is true, or you are not confident enough to answer safely from a knowledge base. Otherwise the literal string 'false'." },
    "escalate_reason": { "type": "string", "description": "One short sentence explaining why escalate is true. Empty string if escalate is false." },
    "confidence": { "type": "number", "description": "0 to 1. Confidence this can be safely answered from a knowledge base without human review." }
  }
}

parameters.text:
