Produce the required structured JSON output.

parameters.inputSchema:
{
  "type": "object",
  "required": ["reply_text", "grounded", "grounding_gap"],
  "properties": {
    "reply_text": { "type": "string", "description": "The full reply to the customer, in the business's tone of voice as captured in the knowledge base answers. No invented facts." },
    "grounded": { "type": "string", "description": "'true' if every claim in reply_text is directly supported by the provided knowledge base context, otherwise 'false'. If you had to guess or infer policy beyond what the context states, this must be 'false'." },
    "grounding_gap": { "type": "string", "description": "If grounded is 'false', one sentence on what was missing. Empty string if grounded is 'true'." }
  }
}

